resources.afterResponseScript:
// Health check tests
const responseBody = insomnia.response.json();
const status = insomnia.response.status;

insomnia.test('✅ Health check successful', () => {
  insomnia.expect(status).to.equal('OK');
});

insomnia.test('✅ Response has status', () => {
  insomnia.expect(responseBody).to.have.property('status');
});

insomnia.test('✅ API is healthy', () => {
  insomnia.expect(responseBody.status).to.equal('healthy');
});

console.log('🏥 Health check completed:', responseBody.status);

// List items tests
const responseBody = insomnia.response.json();
const status = insomnia.response.status;

insomnia.test('✅ Items listed successfully', () => {
  insomnia.expect(status).to.equal('OK');
});

insomnia.test('✅ Response has data array', () => {
  insomnia.expect(responseBody).to.have.property('data');
  insomnia.expect(responseBody.data).to.be.an('array');
});

insomnia.test('📦 Items have required fields', () => {
  if (responseBody.data.length > 0) {
    const item = responseBody.data[0];
    insomnia.expect(item).to.have.property('id');
    insomnia.expect(item).to.have.property('nome');
    insomnia.expect(item).to.have.property('preco');
    insomnia.expect(item).to.have.property('qtd_atual');
  }
});

console.log('📦 Found', responseBody.data.length, 'items');

// Create item tests
const responseBody = insomnia.response.json();
const status = insomnia.response.status;

insomnia.test('✅ Item created successfully', () => {
  insomnia.expect(status).to.equal('Created');
});

insomnia.test('✅ Response has item data', () => {
  insomnia.expect(responseBody).to.have.property('data');
});

insomnia.test('✅ Item has all required fields', () => {
  insomnia.expect(responseBody.data).to.have.property('id');
  insomnia.expect(responseBody.data).to.have.property('nome');
  insomnia.expect(responseBody.data).to.have.property('preco');
  insomnia.expect(responseBody.data).to.have.property('qtd_atual');
});

console.log('📦 Item criado:', responseBody.data.nome);

// Validation error tests
const responseBody = insomnia.response.json();
const status = insomnia.response.status;

insomnia.test('🚫 Validation error - Status Bad Request', () => {
  insomnia.expect(status).to.equal('Bad Request');
});

insomnia.test('✅ Response has error details', () => {
  insomnia.expect(responseBody).to.have.property('error');
});

insomnia.test('✅ Error has validation message', () => {
  insomnia.expect(responseBody.error).to.have.property('message');
});

console.log('🚫 Validation error:', responseBody.error.message);

// Captura automaticamente o ID do item criado e salva na variável de ambiente
const responseBody = insomnia.response.json();
const status = insomnia.response.status;

// Testes
insomnia.test('✅ Status is Created (201)', () => {
  insomnia.expect(status).to.equal('Created');
});

insomnia.test('✅ Response has data object', () => {
  insomnia.expect(responseBody).to.have.property('data');
});

insomnia.test('✅ Item has ID', () => {
  insomnia.expect(responseBody.data).to.have.property('id');
});

insomnia.test('✅ Item has correct stock quantity', () => {
  insomnia.expect(responseBody.data.qtd_atual).to.equal(1);
});

if (responseBody && responseBody.data && responseBody.data.id) {
  // Salva o ID na variável de ambiente
  await insomnia.environment.set('single_item_id', responseBody.data.id.toString());

  // Log para confirmar
  console.log('✅ ID do item capturado automaticamente:', responseBody.data.id);
  console.log('🔄 Variável single_item_id atualizada!');
} else {
  console.log('❌ Erro: Não foi possível capturar o ID do item');
  console.log('Response:', responseBody);
}

// List purchases tests
const responseBody = insomnia.response.json();
const status = insomnia.response.status;

insomnia.test('✅ Purchases listed successfully', () => {
  insomnia.expect(status).to.equal('OK');
});

insomnia.test('✅ Response has data array', () => {
  insomnia.expect(responseBody).to.have.property('data');
  insomnia.expect(responseBody.data).to.be.an('array');
});

insomnia.test('🛒 Purchases have required fields', () => {
  if (responseBody.data.length > 0) {
    const purchase = responseBody.data[0];
    insomnia.expect(purchase).to.have.property('id');
    insomnia.expect(purchase).to.have.property('comprador_github_login');
    insomnia.expect(purchase).to.have.property('item');
  }
});

console.log('🛒 Found', responseBody.data.length, 'purchases');

// Create purchase tests
const responseBody = insomnia.response.json();
const status = insomnia.response.status;

insomnia.test('✅ Purchase created successfully', () => {
  insomnia.expect(status).to.equal('Created');
});

insomnia.test('✅ Response has purchase data', () => {
  insomnia.expect(responseBody).to.have.property('data');
});

insomnia.test('✅ Purchase has buyer info', () => {
  insomnia.expect(responseBody.data).to.have.property('comprador_github_login');
});

insomnia.test('✅ Purchase has item details', () => {
  insomnia.expect(responseBody.data).to.have.property('item');
});

console.log('🛒 Purchase created for:', responseBody.data.comprador_github_login);

// Test for item not found error
const responseBody = insomnia.response.json();
const status = insomnia.response.status;

// Testes
insomnia.test('✅ Status is Bad Request (400)', () => {
  insomnia.expect(status).to.equal('Bad Request');
});

insomnia.test('✅ Response has error object', () => {
  insomnia.expect(responseBody).to.have.property('error');
});

insomnia.test('✅ Error indicates validation issue', () => {
  insomnia.expect(responseBody.error).to.have.property('message');
});

console.log('✅ Validation error handled correctly');
console.log('Status:', status);
console.log('Error:', responseBody?.error?.message);

// Feedback visual do resultado da compra
const responseBody = insomnia.response.json();
const status = insomnia.response.status;

// Testes
insomnia.test('🎉 Purchase successful - Status Created (201)', () => {
  insomnia.expect(status).to.equal('Created');
});

insomnia.test('✅ Response has purchase data', () => {
  insomnia.expect(responseBody).to.have.property('data');
});

insomnia.test('✅ Purchase has buyer GitHub login', () => {
  insomnia.expect(responseBody.data).to.have.property('comprador_github_login');
});

insomnia.test('✅ Purchase has item details', () => {
  insomnia.expect(responseBody.data).to.have.property('item');
  insomnia.expect(responseBody.data.item).to.have.property('nome');
  insomnia.expect(responseBody.data.item).to.have.property('preco');
});

insomnia.test('📊 Stock was decremented to 0', () => {
  insomnia.expect(responseBody.data.item.qtd_atual).to.equal(0);
});

if (status === 'Created' && responseBody && responseBody.data) {
  console.log('🎉 COMPRA REALIZADA COM SUCESSO!');
  console.log('👤 Comprador GitHub:', responseBody.data.comprador_github_login);
  console.log('📦 Item:', responseBody.data.item.nome);
  console.log('💰 Preço:', responseBody.data.item.preco);
  console.log('📊 Estoque restante:', responseBody.data.item.qtd_atual);
} else {
  console.log('❌ Erro na compra:', responseBody?.error?.message || 'Erro desconhecido');
}

// Feedback visual do erro de estoque
const responseBody = insomnia.response.json();
const status = insomnia.response.status;

// Testes
insomnia.test('🚫 Stock error - Status Unprocessable Entity (422)', () => {
  insomnia.expect(status).to.equal('Unprocessable Entity');
});

insomnia.test('✅ Response has error object', () => {
  insomnia.expect(responseBody).to.have.property('error');
});

insomnia.test('✅ Error has correct code', () => {
  insomnia.expect(responseBody.error).to.have.property('code');
});

insomnia.test('✅ Error has message', () => {
  insomnia.expect(responseBody.error).to.have.property('message');
});

insomnia.test('✅ Error has stock details', () => {
  insomnia.expect(responseBody.error).to.have.property('details');
  insomnia.expect(responseBody.error.details).to.have.property('current_stock');
});

insomnia.test('📊 Current stock is 0', () => {
  insomnia.expect(responseBody.error.details.current_stock).to.equal(0);
});

if (status === 'Unprocessable Entity' && responseBody && responseBody.error) {
  console.log('✅ ERRO DE ESTOQUE CAPTURADO CORRETAMENTE!');
  console.log('🚫 Código:', responseBody.error.code);
  console.log('� Mensageem:', responseBody.error.message);
  console.log('📊 Estoque atual:', responseBody.error.details.current_stock);
  console.log('🎯 CONTROLE DE ESTOQUE FUNCIONANDO PERFEITAMENTE!');
} else {
  console.log('⚠️ Resposta inesperada. Status:', status);
  console.log('📄 Response:', responseBody);
}

// Swagger docs tests
const status = insomnia.response.status;

insomnia.test('✅ Documentation accessible', () => {
  insomnia.expect(status).to.equal('OK');
});

insomnia.test('📚 Swagger UI loaded', () => {
  const body = insomnia.response.text();
  insomnia.expect(body).to.include('swagger');
});

console.log('📚 Swagger documentation loaded successfully');

// Swagger JSON tests
const responseBody = insomnia.response.json();
const status = insomnia.response.status;

insomnia.test('✅ Swagger JSON accessible', () => {
  insomnia.expect(status).to.equal('OK');
});

insomnia.test('✅ Valid OpenAPI spec', () => {
  insomnia.expect(responseBody).to.have.property('openapi');
  insomnia.expect(responseBody).to.have.property('info');
  insomnia.expect(responseBody).to.have.property('paths');
});

insomnia.test('📋 API info present', () => {
  insomnia.expect(responseBody.info).to.have.property('title');
  insomnia.expect(responseBody.info).to.have.property('version');
});

console.log('📋 API:', responseBody.info.title, 'v' + responseBody.info.version);
